const PF_TODAS: TipoForma[] = ["shikai", "bankai", "bankai2", "resurreccion", "segunda", "vollstandig"];

const A = (v: number, atr: Atr = "for"): Efeito => ({ k: "atr", atr, v });
const todos = (v: number): Efeito[] => (["for", "des", "con", "men", "esp"] as Atr[]).map((a) => A(v, a));

